signature.code:
createCollection<T>(config: {
  getId: (entity: T) => string;
  sortBy?: (a: T, b: T) => number;
}): Collection<T>

examples.code:
import { createCollection } from 'qortex-resource';

type Todo = { id: string; title: string; done: boolean };

const todos = createCollection<Todo>({
  getId: (t) => t.id,
  sortBy: (a, b) => Number(a.done) - Number(b.done),
});

// Seed from API
const rows = await api.todos.list();
todos.setAll(rows);

todos.selectCount(); // rows.length
todos.selectIds();   // ordered ids

todos.addOne({ id: '1', title: 'Ship alpha', done: false });
todos.addMany([
  { id: '2', title: 'Docs', done: false },
  { id: '3', title: 'Tests', done: true },
]);

todos.updateOne('1', { title: 'Ship alpha docs' });
todos.updateOne('2', (prev) => ({ ...prev, done: true }));
todos.updateMany(['1', '2'], { done: false });

todos.upsertOne({ id: '1', title: 'Updated', done: false });

todos.removeOne('3');
todos.removeMany(['1', '2']);
todos.removeAll();

const row = todos.getResource('1');

row.set('title', 'Edited locally');
row.snapshot.isChanged; // true

await row.save();
// collection entity '1' now has title 'Edited locally'
// draft cleared

row.resetDraft(); // discard without save

// Same id → same instance
todos.getResource('1') === row; // true

// remove destroys the cached resource
todos.removeOne('1');

const unsub = todos.subscribe(() => {
  console.log('version', todos.version, todos.selectAll());
});

const unsubOne = todos.subscribeOne('1', (entity) => {
  console.log('entity 1', entity);
});

unsub();
unsubOne();
todos.destroy();

const row = todos.getResource('1');
row.set('title', 'local edit');

// External patch (e.g. websocket)
todos.updateOne('1', { title: 'from server', done: true });
// row resource source updates; dirty override on 'title' may keepDirty
